/**
 * Unit tests of this module have no database. Opening one here would pin the
 * process-wide client to a file before other suites point it at their own
 * database. A configured path or an already-open client is fair game.
 */
function shouldReadPlanFromDatabase(): boolean {
  if (process.env.TASKFLOW_DB_PATH) return true;
  if (isDatabaseOpen()) return true;
  return process.env.NODE_ENV !== "test";
}

/**
 * Subscription plan, else the plan stored on the workspace, else the explicit
 * fallback. Each org is resolved on its own so one workspace cannot size
 * another's bucket.
 */
async function planForOrg(orgId: OrgId): Promise<PlanId> {
  if (shouldReadPlanFromDatabase()) {
    try {
      const { findOrgById } = await import(
        "@/server/repositories/organization-repository"
      );
      const org = await findOrgById(orgId);
      if (org) return org.plan;
    } catch {
      // No schema yet. The explicit map below still applies.
    }
  }
  return planByOrg.get(orgId) ?? "free";
}

function configFor(plan: PlanId, bucketKey: string): RateLimitConfig {
  const base = getBucketConfig(bucketKey);
  const hourly = getPlanLimits(plan).apiRequestsPerHour;
  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;

  return {
    capacity: Math.min(base.capacity * factor, base.capacity * 100),
    refillPerMinute: Math.min(
      base.refillPerMinute * factor,
      base.refillPerMinute * 100,
    ),
  };
}

